/**
 * Test file for SLA Percentage Timer action with hidden inputs
 *
 * Hidden inputs (should NOT appear in user code):
 * - task_sla_record (ReferenceColumn with visible_in_fd: false, has default)
 * - sla_flow_inputs (FlowObject with visible_in_fd: false, has default)
 *
 * Visible inputs (should appear in user code):
 * - percentage (IntegerColumn, mandatory)
 */

import { Flow, wfa, trigger, action } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['flow_sla_timer_hidden_test'],
        name: 'SLA Timer Hidden Inputs Test',
        description: 'Tests SLA Percentage Timer action with hidden inputs',
        runAs: 'system',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['trigger_sla_task'] },
        {
            table: 'task',
            condition: 'priority=1',
        }
    ),
    (_params) => {
        // Only visible input (percentage) should be required
        // Hidden inputs (task_sla_record, sla_flow_inputs) should NOT appear here
        wfa.action(
            action.core.slaPercentageTimer,
            {
                $id: Now.ID['action_sla_timer'],
                annotation: 'Wait for 50% of SLA duration',
            },
            {
                percentage: 50,
            }
        )
    }
)
